<?php
declare(strict_types=1);

final class ChatJobService {
 private string $root;
 private string $storage;
 public function __construct(private PDO $db,array $config){$this->root=dirname(__DIR__,2);$this->storage=(string)$config['storage'];}
 public function enqueue(string $sessionId,string $providerId,string $model,string $message,array $history,?string $taskInboxId=null):array{
  $message=trim($message);if($message==='')throw new InvalidArgumentException('Chat message cannot be empty.');if(mb_strlen($message)>50000)throw new InvalidArgumentException('Chat message is too long.');
  $q=$this->db->prepare('SELECT id FROM chat_sessions WHERE id=?');$q->execute([$sessionId]);if(!$q->fetchColumn())throw new InvalidArgumentException('Chat session does not exist.');
  $model=trim($model);if($model==='')throw new InvalidArgumentException('A model must be selected before queueing a chat job.');if($providerId!=='ollama'){$q=$this->db->prepare('SELECT id FROM providers WHERE id=? AND enabled=1');$q->execute([$providerId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The selected provider is missing or disabled.');}
  if($taskInboxId!==null&&$taskInboxId!==''){$q=$this->db->prepare("SELECT id FROM task_inbox WHERE id=? AND status='queued' AND (session_id IS NULL OR session_id=?)");$q->execute([$taskInboxId,$sessionId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The selected Task Inbox item is no longer queued for this chat.');}else{$taskInboxId=null;}
  $id='job_'.bin2hex(random_bytes(12));$now=date(DATE_ATOM);$historyJson=json_encode(array_slice($history,-30),JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);
  $this->db->beginTransaction();try{$m=$this->db->prepare('INSERT INTO chat_messages(session_id,role,content,created_at) VALUES(?,?,?,?)');$m->execute([$sessionId,'user',$message,$now]);$j=$this->db->prepare("INSERT INTO chat_jobs(id,session_id,provider_id,model,message,history_json,task_inbox_id,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'queued',?,?)");$j->execute([$id,$sessionId,$providerId,$model,$message,$historyJson,$taskInboxId,$now,$now]);$u=$this->db->prepare('UPDATE chat_sessions SET updated_at=? WHERE id=?');$u->execute([$now,$sessionId]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
  return $this->get($id);
 }
 public function startWorker(string $id):void{
  if(!preg_match('/^job_[a-f0-9]{24}$/',$id))throw new InvalidArgumentException('Invalid chat job ID.');$worker=$this->root.'/bin/chat-worker.php';if(!is_file($worker))throw new RuntimeException('DCP chat worker script is missing.');$logs=$this->storage.'/logs';if(!is_dir($logs)&&!mkdir($logs,0700,true)&&!is_dir($logs))throw new RuntimeException('Cannot create chat worker log directory.');$logOut=$logs.'/chat-'.$id.'.out.log';$logErr=$logs.'/chat-'.$id.'.err.log';
  if(PHP_OS_FAMILY==='Windows'){$script=$this->storage.'/start-chat-worker.cmd';$php=str_replace('%','%%',PHP_BINARY);$workerEsc=str_replace('%','%%',$worker);$idEsc=$id;$logOutEsc=str_replace('%','%%',$logOut);$logErrEsc=str_replace('%','%%',$logErr);$body="@echo off\r\n\"{$php}\" \"{$workerEsc}\" \"{$idEsc}\" 1>\"{$logOutEsc}\" 2>\"{$logErrEsc}\"\r\n";if(file_put_contents($script,$body)===false)throw new RuntimeException('Cannot write chat worker launcher.');$command='start "" /B cmd.exe /D /C '.escapeshellarg($script).' & echo STARTED';$pipe=@popen($command,'r');if(!is_resource($pipe))throw new RuntimeException('Could not create detached Windows chat worker process.');$marker=fgets($pipe);$exit=pclose($pipe);$started=$exit===0&&trim((string)$marker)==='STARTED'?'STARTED':'';
  }else{$cmd='nohup '.escapeshellarg(PHP_BINARY).' '.escapeshellarg($worker).' '.escapeshellarg($id).' > '.escapeshellarg($logOut).' 2> '.escapeshellarg($logErr).' < /dev/null & echo STARTED';$started=$this->runCommand($cmd,5);}
  if(trim($started)!=='STARTED'){$current=$this->get($id);if(in_array($current['status'],['running','completed','checkpoint_requested','checkpoint_ready'],true))return;throw new RuntimeException('Could not detach the background chat worker. '.trim($started));}
 }

 public function claim(string $id):?array{$now=date(DATE_ATOM);$lease=date(DATE_ATOM,time()+1800);$this->db->beginTransaction();try{$q=$this->db->prepare("UPDATE chat_jobs SET status='running',started_at=?,updated_at=?,lease_until=?,worker_pid=? WHERE id=? AND status='queued' AND interrupt_requested=0");$q->execute([$now,$now,$lease,getmypid(),$id]);if(!$q->rowCount()){$this->db->commit();return null;}$q=$this->db->prepare('SELECT * FROM chat_jobs WHERE id=?');$q->execute([$id]);$job=$q->fetch()?:null;$this->db->commit();if($job)$job['history']=json_decode((string)$job['history_json'],true)?:[];return $job;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function complete(string $id,string $reply):array{$this->db->beginTransaction();try{$q=$this->db->prepare('SELECT session_id,task_inbox_id,interrupt_requested,status,provider_id,model,message FROM chat_jobs WHERE id=?');$q->execute([$id]);$job=$q->fetch();if(!$job||!in_array($job['status'],['running','checkpoint_requested'],true))throw new RuntimeException('Chat job is no longer active.');$now=date(DATE_ATOM);$status=(int)$job['interrupt_requested']===1?'checkpoint_ready':'completed';$m=$this->db->prepare('INSERT INTO chat_messages(session_id,role,content,created_at) VALUES(?,?,?,?)');$m->execute([$job['session_id'],'assistant',$reply,$now]);$u=$this->db->prepare("UPDATE chat_jobs SET status=?,reply=?,error=NULL,updated_at=?,completed_at=?,lease_until=NULL WHERE id=? AND status IN ('running','checkpoint_requested')");$u->execute([$status,$reply,$now,$now,$id]);if(!$u->rowCount())throw new RuntimeException('Chat job state changed before completion was committed.');$s=$this->db->prepare('UPDATE chat_sessions SET updated_at=? WHERE id=?');$s->execute([$now,$job['session_id']]);if(is_string($job['task_inbox_id'])&&$job['task_inbox_id']!==''){$q=$this->db->prepare("UPDATE task_inbox SET status='sent',updated_at=? WHERE id=? AND status='queued'");$q->execute([$now,$job['task_inbox_id']]);}if($status==='checkpoint_ready')$this->createCheckpoint($id,'provider_call_complete');$this->db->commit();return $this->get($id);}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function fail(string $id,string $error):void{$error=mb_substr(trim($error),0,2000);$now=date(DATE_ATOM);$q=$this->db->prepare("UPDATE chat_jobs SET status='failed',error=?,updated_at=?,completed_at=?,lease_until=NULL WHERE id=? AND status IN ('queued','running','checkpoint_requested')");$q->execute([$error!==''?$error:'Chat worker failed.',$now,$now,$id]);}
 public function requestCheckpoint(string $id):array{$now=date(DATE_ATOM);$this->db->beginTransaction();try{$q=$this->db->prepare("UPDATE chat_jobs SET interrupt_requested=1,status=CASE WHEN status='queued' THEN 'checkpoint_ready' WHEN status='running' THEN 'checkpoint_requested' ELSE status END,updated_at=?,completed_at=CASE WHEN status='queued' THEN ? ELSE completed_at END,lease_until=CASE WHEN status='queued' THEN NULL ELSE lease_until END WHERE id=? AND status IN ('queued','running','checkpoint_requested')");$q->execute([$now,$now,$id]);if(!$q->rowCount())throw new RuntimeException('Chat job is no longer active; there is no checkpoint to request.');$q=$this->db->prepare('SELECT status FROM chat_jobs WHERE id=?');$q->execute([$id]);if($q->fetchColumn()==='checkpoint_ready')$this->createCheckpoint($id,'paused_before_provider');$this->db->commit();return $this->get($id);}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}

 public function get(string $id):array{$this->recoverExpired($id);$q=$this->db->prepare('SELECT id,session_id,provider_id,model,status,reply,error,interrupt_requested,worker_pid,checkpoint_id,created_at,updated_at,started_at,completed_at FROM chat_jobs WHERE id=?');$q->execute([$id]);$job=$q->fetch();if(!$job)throw new RuntimeException('Chat job not found.');$job['interrupt_requested']=(bool)$job['interrupt_requested'];return $job;}
 public function getCheckpoint(string $jobId):array{$q=$this->db->prepare('SELECT id,job_id,session_id,checkpoint_kind,context_hash,snapshot_json,created_at FROM chat_job_checkpoints WHERE job_id=?');$q->execute([$jobId]);$row=$q->fetch();if(!$row)throw new RuntimeException('No durable checkpoint exists for this chat job.');$row['snapshot']=json_decode((string)$row['snapshot_json'],true,512,JSON_THROW_ON_ERROR);unset($row['snapshot_json']);return $row;}
 private function createCheckpoint(string $jobId,string $kind):string{$existing=$this->db->prepare('SELECT id FROM chat_job_checkpoints WHERE job_id=?');$existing->execute([$jobId]);$existingId=$existing->fetchColumn();if($existingId)return (string)$existingId;$q=$this->db->prepare('SELECT id,session_id,provider_id,model,message,status,reply,completed_at FROM chat_jobs WHERE id=?');$q->execute([$jobId]);$job=$q->fetch();if(!$job)throw new RuntimeException('Cannot snapshot a missing chat job.');$messages=$this->db->prepare('SELECT role,content,created_at FROM chat_messages WHERE session_id=? ORDER BY id DESC LIMIT 30');$messages->execute([$job['session_id']]);$conversation=array_reverse($messages->fetchAll());$pending=$this->db->prepare("SELECT id,message,priority,created_at,session_id FROM task_inbox WHERE status='queued' AND (session_id IS NULL OR session_id=?) ORDER BY priority,created_at,id LIMIT 50");$pending->execute([$job['session_id']]);$snapshot=['schema_version'=>1,'job_id'=>$job['id'],'session_id'=>$job['session_id'],'provider_id'=>$job['provider_id'],'model'=>$job['model'],'checkpoint_kind'=>$kind,'job_status'=>$job['status'],'captured_at'=>date(DATE_ATOM),'last_provider_call'=>['user_message'=>$job['message'],'assistant_reply'=>$job['reply'],'completed_at'=>$job['completed_at']],'conversation_context'=>$conversation,'pending_instructions'=>$pending->fetchAll(),'human_review_required'=>true,'automatic_execution'=>false,'next_action'=>'Review pending instructions and explicitly choose which, if any, to insert into the chat.' ];$json=json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);$hash=hash('sha256',$json);$checkpointId='ckpt_'.bin2hex(random_bytes(12));$now=date(DATE_ATOM);$insert=$this->db->prepare('INSERT INTO chat_job_checkpoints(id,job_id,session_id,checkpoint_kind,context_hash,snapshot_json,created_at) VALUES(?,?,?,?,?,?,?)');$insert->execute([$checkpointId,$jobId,$job['session_id'],$kind,$hash,$json,$now]);$update=$this->db->prepare('UPDATE chat_jobs SET checkpoint_id=?,updated_at=? WHERE id=?');$update->execute([$checkpointId,$now,$jobId]);return $checkpointId;}
 public function active(string $sessionId):?array{$q=$this->db->prepare("SELECT id FROM chat_jobs WHERE session_id=? AND status IN ('queued','running','checkpoint_requested') ORDER BY created_at DESC LIMIT 1");$q->execute([$sessionId]);$id=$q->fetchColumn();return $id?$this->get((string)$id):null;}
 private function recoverExpired(string $id):void{$now=date(DATE_ATOM);$q=$this->db->prepare("UPDATE chat_jobs SET status='failed',error='Chat worker lease expired. Review the conversation and retry manually.',updated_at=?,completed_at=?,lease_until=NULL WHERE id=? AND status IN ('running','checkpoint_requested') AND lease_until IS NOT NULL AND julianday(lease_until)<julianday(?)");$q->execute([$now,$now,$id,$now]);}
 private function runCommand(string|array $command,int $timeout):string{$spec=[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']];$proc=@proc_open($command,$spec,$pipes,$this->root);if(!is_resource($proc))return '';fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$stdout='';$started=microtime(true);$exit=-1;do{$stdout.=stream_get_contents($pipes[1])?:'';stream_get_contents($pipes[2]);$status=proc_get_status($proc);if(!$status['running']){$exit=(int)$status['exitcode'];break;}if(microtime(true)-$started>$timeout){proc_terminate($proc,9);$exit=124;break;}usleep(50000);}while(true);$stdout.=stream_get_contents($pipes[1])?:'';fclose($pipes[1]);fclose($pipes[2]);$closed=proc_close($proc);if($exit<0)$exit=$closed;return $exit===0?trim($stdout):'';}
}
